INSERT INTO conversation_topics (title, category, difficulty_level, description, content, vocabulary) VALUES
('Pet Ownership Benefits', 'Pets', 'Beginner', 'How pets improve lives', 'Pets provide companionship and reduce stress. Dogs encourage exercise through walks. Cats offer calm presence. Pet ownership teaches responsibility, especially for children. The human-animal bond is therapeutic. Pets help combat loneliness and depression. Studies show pet owners have better mental health.', ARRAY['pet', 'companionship', 'responsibility', 'therapeutic', 'bond']),
('Exotic Pet Care', 'Pets', 'Intermediate', 'Caring for unusual animals', 'Exotic pets like reptiles and birds need specialized care. Temperature and humidity must be controlled. Each species has unique dietary requirements. Research is essential before adoption. Veterinary care can be expensive. Understanding natural habitat helps provide proper environment.', ARRAY['exotic', 'reptile', 'habitat', 'specialized', 'veterinary']),
('Service Animals', 'Pets', 'Advanced', 'Animals assisting people', 'Service animals perform tasks for people with disabilities. Guide dogs help visually impaired navigate safely. Hearing dogs alert deaf individuals to sounds. Therapy animals provide emotional support. Training is extensive and specialized. Service animals have legal access rights to public spaces.', ARRAY['service animal', 'disability', 'therapy', 'assistance', 'training']),
('Pet Training Methods', 'Pets', 'Beginner', 'Teaching good behavior', 'Positive reinforcement is most effective. Reward desired behaviors immediately. Consistency is crucial for success. Start training early with puppies. Basic commands include sit, stay, come. Patience required as animals learn at different rates.', ARRAY['training', 'positive reinforcement', 'behavior', 'consistency', 'reward']),
('Wildlife Conservation', 'Pets', 'Advanced', 'Protecting endangered species', 'Many species face extinction from habitat loss. Conservation programs include breeding and protection. International cooperation is essential. Climate change threatens ecosystems. Individual actions like reducing plastic help. Ecotourism funds conservation efforts.', ARRAY['conservation', 'extinction', 'ecosystem', 'biodiversity', 'habitat']),
('Veterinary Medicine', 'Pets', 'Intermediate', 'Pet healthcare', 'Regular checkups prevent serious illness. Vaccinations protect against disease. Dental care is often overlooked. Parasites need prevention treatment. Emergency care can be expensive. Pet insurance helps manage costs.', ARRAY['veterinary', 'vaccination', 'healthcare', 'prevention', 'parasite']),
('Animal Communication', 'Pets', 'Advanced', 'Understanding animal behavior', 'Animals use body language and vocalizations. Dogs communicate through tail wagging and ear position. Cats use meowing, purring, and body posture. Understanding signals strengthens bonds. Stress signals indicate fear or discomfort. Research reveals animal intelligence.', ARRAY['communication', 'body language', 'behavior', 'vocalization', 'intelligence']),
('Pet Nutrition', 'Pets', 'Intermediate', 'Proper pet feeding', 'Quality pet food provides balanced nutrition. Overfeeding causes obesity problems. Some human foods are toxic to pets. Fresh water should always be available. Age affects dietary needs. Consult veterinarians about nutrition.', ARRAY['nutrition', 'diet', 'obesity', 'feeding', 'balanced']),
('Pet Industry Trends', 'Pets', 'Advanced', 'Business of pet care', 'Pet industry worth billions globally. Services include grooming, boarding, daycare. Technology brings smart feeders and health trackers. Veterinary medicine advances rapidly. Pet insurance is growing. Premium products dominate market.', ARRAY['industry', 'business', 'technology', 'market', 'innovation']),
('Animal Rights', 'Pets', 'Advanced', 'Ethics of animal treatment', 'Animals deserve humane treatment. Factory farming raises ethical concerns. Animal testing for cosmetics is controversial. Wildlife trade threatens species. Laws protect animals from cruelty. Balance exists between use and welfare.', ARRAY['animal rights', 'ethics', 'welfare', 'cruelty', 'protection']),
('Essential Vitamins', 'Health', 'Beginner', 'Vitamins your body needs', 'Vitamins are essential for health. Vitamin C supports immune system. Vitamin D crucial for bones from sunlight. B vitamins provide energy. Vitamin A maintains vision. Most come from balanced diet.', ARRAY['vitamin', 'nutrition', 'immune system', 'health', 'deficiency']),
('Protein Supplements', 'Health', 'Intermediate', 'Muscle building supplements', 'Protein helps build muscle tissue. Whey protein absorbs quickly. Plant-based proteins suit vegetarians. Timing intake optimizes growth. Most people get enough from food. Athletes have higher requirements.', ARRAY['protein', 'muscle', 'supplement', 'fitness', 'nutrition']),
('Omega-3 Benefits', 'Health', 'Intermediate', 'Essential fatty acids', 'Omega-3s reduce inflammation. Support heart and brain health. Found in fish, flaxseeds, walnuts. Fish oil supplements are popular. EPA and DHA are main types. Choose purified quality supplements.', ARRAY['omega-3', 'fatty acid', 'heart health', 'inflammation', 'fish oil']),
('Probiotics', 'Health', 'Advanced', 'Gut health bacteria', 'Probiotics are beneficial bacteria. Restore gut flora after antibiotics. Fermented foods contain probiotics naturally. Different strains have different benefits. Gut microbiome affects overall health. Not all supplements equally effective.', ARRAY['probiotic', 'gut health', 'bacteria', 'microbiome', 'fermented']),
('Herbal Supplements', 'Health', 'Advanced', 'Plant-based remedies', 'Herbs used for centuries medicinally. Ginger helps nausea. Turmeric has anti-inflammatory properties. Scientific evidence varies. Natural doesn't mean safe. Can interact with medications.', ARRAY['herbal', 'remedy', 'traditional medicine', 'natural', 'supplement']),
('Sports Nutrition', 'Health', 'Advanced', 'Athletic supplements', 'Athletes have unique nutritional needs. Creatine improves strength. Beta-alanine buffers lactic acid. Timing affects performance. Many lack strong evidence. Whole foods should be foundation.', ARRAY['sports nutrition', 'athletic', 'performance', 'supplement', 'fitness']),
('Multivitamins', 'Health', 'Beginner', 'All-in-one supplements', 'Provide various nutrients in one pill. Help prevent deficiencies. Not everyone needs them. Quality varies among brands. Taking with food improves absorption. Specific populations benefit more.', ARRAY['multivitamin', 'nutrition', 'supplement', 'deficiency', 'health']),
('Vitamin D Deficiency', 'Health', 'Intermediate', 'Sunshine vitamin importance', 'Many people are deficient in vitamin D. Sunlight produces it in skin. Supports bone health and immunity. Few foods contain it naturally. Supplements often recommended. Testing determines your levels.', ARRAY['vitamin D', 'deficiency', 'sunlight', 'bone health', 'immunity']),
('Antioxidants', 'Health', 'Advanced', 'Fighting free radicals', 'Protect cells from oxidative stress. Free radicals damage cells. Vitamins C and E are antioxidants. Colorful fruits rich in antioxidants. Food sources may be better. Excessive supplementation may interfere.', ARRAY['antioxidant', 'oxidative stress', 'free radical', 'vitamin', 'health']),
('Supplement Safety', 'Health', 'Advanced', 'Safe supplement use', 'Supplements not strictly regulated. Quality varies among manufacturers. Can interact with medications. More isn't always better. Third-party testing provides assurance. Inform doctors about supplements taken.', ARRAY['safety', 'regulation', 'interaction', 'quality', 'health']);